import{_ as r,o as t,c as o,a2 as e}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"神权体系","description":"","frontmatter":{},"headers":[],"relativePath":"底层/规则/神权体系.md","filePath":"底层/规则/神权体系.md","lastUpdated":null}'),l={name:"底层/规则/神权体系.md"};function n(i,a,s,h,u,d){return t(),o("div",null,[...a[0]||(a[0]=[e('<h1 id="神权体系" tabindex="-1">神权体系 <a class="header-anchor" href="#神权体系" aria-label="Permalink to &quot;神权体系&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>神权体系是神造物世界观的核心底层设定，定义了创造、变化、毁灭三大神权的本质、规则与运作机制。神权等同于世界的作者级管理员权限，三者功能互补构成完备体系。这一体系由初代变化神建立和完善，构成了整个世界观的神权运作基础。</p><h2 id="神权的本质与起源" tabindex="-1">神权的本质与起源 <a class="header-anchor" href="#神权的本质与起源" aria-label="Permalink to &quot;神权的本质与起源&quot;">​</a></h2><p><strong>神权</strong>一名为初代变化神在探究世界本质时为其取的名字（其本质上为作者的三大创作权，这三个权柄加起来可以做的事情与作者可以做的事情没有任何区别）。</p><h3 id="神权分类" tabindex="-1">神权分类 <a class="header-anchor" href="#神权分类" aria-label="Permalink to &quot;神权分类&quot;">​</a></h3><p>创造、变化、毁灭三大神权等同于世界的作者级管理员权限，三者功能互补构成完备体系：</p><ul><li><strong>创造神权</strong>：可创造字面意义上的一切事物（含合理/不合理的致命悖论）</li><li><strong>变化神权</strong>：可修改、调整既有的存在</li><li><strong>毁灭神权</strong>：可删除任何东西，甚至包括时空、因果等宇宙的底层逻辑</li></ul><p>任一神权本源永久性消失，世界都会走向根本性毁灭。</p><h3 id="命名与称谓" tabindex="-1">命名与称谓 <a class="header-anchor" href="#命名与称谓" aria-label="Permalink to &quot;命名与称谓&quot;">​</a></h3><p>初代变化神称掌握神权的实体为<strong>神明</strong>，并根据神权种类不同分为创造神、变化神、毁灭神三种，后续延续了该称呼。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../../中层/世界/历代三神" class="layer-link" data-layer="中层">历代三神</a></p></blockquote><h2 id="使用代价与宏愿" tabindex="-1">使用代价与宏愿 <a class="header-anchor" href="#使用代价与宏愿" aria-label="Permalink to &quot;使用代价与宏愿&quot;">​</a></h2><h3 id="代价机制" tabindex="-1">代价机制 <a class="header-anchor" href="#代价机制" aria-label="Permalink to &quot;代价机制&quot;">​</a></h3><p>初代变化神为限制神权而制定的规则，神权承载对象会因过度使用神权而受到概念层面的伤害。这种伤害能以完全无视逻辑的方式（无法检测、无法绕过、无法抵抗、无法治疗）使神权承载对象受伤乃至失能、死亡，只能通过时间的缓慢流逝自行恢复。初代变化神将其命名为<strong>使用神权的代价</strong>。</p><p>对于过度使用的判定遵循某种特定规则，目前仅能确认其与影响规模相关，初代变化神所制定的具体规则细节至今仍未明确。</p><h3 id="宏愿机制" tabindex="-1">宏愿机制 <a class="header-anchor" href="#宏愿机制" aria-label="Permalink to &quot;宏愿机制&quot;">​</a></h3><p>由于代价存在上限（最高可导致载体消亡），所有在现实世界内拥有神权的神明皆可在死亡前无限制地使用一次神权，初代变化神称之为<strong>宏愿</strong>。初代变化神自身也因制定这一规则而&quot;消亡&quot;。</p><h2 id="神权互斥规则" tabindex="-1">神权互斥规则 <a class="header-anchor" href="#神权互斥规则" aria-label="Permalink to &quot;神权互斥规则&quot;">​</a></h2><p>为了防止神权之间互相影响而让世界永久失去某一神权，初代变化神在宏愿当中立下规则，使得神权与神权之间无法互相影响，从而保证三神权永久完备性。</p><h3 id="上位创造的例外先例" tabindex="-1">上位创造的例外先例 <a class="header-anchor" href="#上位创造的例外先例" aria-label="Permalink to &quot;上位创造的例外先例&quot;">​</a></h3><p>互斥规则本身并非绝对——<strong>上位神权凌驾于下位神权之上</strong>。神机曾以此创造新规则阻止下位神权运作（创造&quot;下位神权无法修改编辑基底层&quot;这一新规则，使维斯塔的宏愿卡入悖论），此为&quot;上位创造立新规&quot;的先例，亦是互斥规则在极少数情况下的例外。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../../中层/世界/地脉与魔法" class="layer-link" data-layer="中层">地脉与魔法</a></p></blockquote><h2 id="神权继承规则" tabindex="-1">神权继承规则 <a class="header-anchor" href="#神权继承规则" aria-label="Permalink to &quot;神权继承规则&quot;">​</a></h2><p>为了便于让自己的造物继承自己的神权，初代变化神规定了神权承载者可以用宏愿指定某实体&quot;继承自己的神权&quot;。而当神权承载者未指定时，下一代神权承载者也会在当前神权承载者的&quot;附近&quot;出现，注意这里的附近为宇宙尺度上的附近，其仍旧为天文尺度，只不过能将范围从整个宇宙缩小至太阳系以内。</p><h2 id="神权的唯一性" tabindex="-1">神权的唯一性 <a class="header-anchor" href="#神权的唯一性" aria-label="Permalink to &quot;神权的唯一性&quot;">​</a></h2><p>神权具有<strong>唯一性</strong>，其在同一时期只能存在一个承载神权的意识。这体现为即使继承者出现了一定的神明特质，其在上一任神明彻底失去意识前也无法成为真正的神明、掌控神权。这个规则来自于神权本身的特质，非初代创造神所规定。</p><h2 id="神权跟随意识原则" tabindex="-1">神权跟随意识原则 <a class="header-anchor" href="#神权跟随意识原则" aria-label="Permalink to &quot;神权跟随意识原则&quot;">​</a></h2><ul><li><strong>同意识多躯体</strong>：若两具躯体具有同一的意识，这两具躯体便都可以掌控神权——因为其本质上是一个意识</li><li><strong>一躯体多意识</strong>：若一具躯体有不同的意识，这一具躯体需看情况才可掌控神权——因为其本质上是多个意识</li></ul><h2 id="上位与下位神权划分" tabindex="-1">上位与下位神权划分 <a class="header-anchor" href="#上位与下位神权划分" aria-label="Permalink to &quot;上位与下位神权划分&quot;">​</a></h2><p>初代变化神许下宏愿，将所有神权分为<strong>上位</strong>与<strong>下位</strong>两类：</p><h3 id="上位神权" tabindex="-1">上位神权 <a class="header-anchor" href="#上位神权" aria-label="Permalink to &quot;上位神权&quot;">​</a></h3><p>将其中极度危险、真正意义上无所不能的部分分为了上位：</p><ul><li><strong>上位创造</strong>：字面意义上的创造一切，无论是否合理，极端危险。在初代变化神划分上下位后，其被神机从初代创造神身上所剥离，目前被神机所掌控。</li><li><strong>上位变化</strong>：字面意义上的改变一切，无论是否合理，极端危险。目前有初代变化神的意识，其严格看守着上位变化，将其连同自己的意识一同禁锢在了基底层之中。</li><li><strong>上位毁灭</strong>：字面意义上的删除一切，无论是否合理，极端危险。目前卡在自我毁灭的悖论中——初代载体（小白狼）曾尝试删除自身神权，但因神权逻辑悖论（无法彻底删除自身）而未能完全成功，只需主动停止便会完全回归。其在本世界观的剧情发展中起到关键作用。</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./../人物/上位毁灭神">上位毁灭神</a></p></blockquote><blockquote><p><strong>详细内容参见</strong>：<a href="./基底层与现实世界">基底层与现实世界</a></p></blockquote><h3 id="下位神权" tabindex="-1">下位神权 <a class="header-anchor" href="#下位神权" aria-label="Permalink to &quot;下位神权&quot;">​</a></h3><p>那些负责架构并管理物质世界，但对底层逻辑无法做手脚的部分分为了下位。一般来讲，不名文加入上位二字的，就都是下位神权。</p><h3 id="神机的特殊地位" tabindex="-1">神机的特殊地位 <a class="header-anchor" href="#神机的特殊地位" aria-label="Permalink to &quot;神机的特殊地位&quot;">​</a></h3><p>当前时代的创造神（二代创造神）实际上掌握的是<strong>上位创造神权</strong>，但她将其伪装成下位神权的样子。这一选择体现了她&quot;掌控危险而非防御危险&quot;的核心理念，与初代变化神&quot;看守危险神权&quot;的理念形成鲜明对比。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../../中层/世界/神机谋划" class="layer-link" data-layer="中层">神机谋划</a></p></blockquote><h2 id="时间线不可干预性" tabindex="-1">时间线不可干预性 <a class="header-anchor" href="#时间线不可干预性" aria-label="Permalink to &quot;时间线不可干预性&quot;">​</a></h2><p>在这个世界观中，<strong>时间是一个很现实、很底层的设定</strong>甚至与未来、过去、时间线是否真实存在，都是个问题。未来、过去没人能动，包括神机也无法干预时间线。</p><h3 id="时间线的固定性" tabindex="-1">时间线的固定性 <a class="header-anchor" href="#时间线的固定性" aria-label="Permalink to &quot;时间线的固定性&quot;">​</a></h3><p>时间线不是不能动的，但只有<strong>玩家</strong>作为特殊的叙事存在可以对时间线进行操作（存档、读档、创造平行世界线）。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./叙事与玩家">叙事与玩家</a></p></blockquote><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><p><a href="./../../叙事与伏笔/伏笔洋葱层分类">伏笔洋葱层分类</a></p></li><li><p><a href="./基底层与现实世界">基底层与现实世界</a></p></li><li><p><a href="./叙事与玩家">叙事与玩家</a></p></li><li><p><a href="./../../中层/世界/历代三神" class="layer-link" data-layer="中层">历代三神</a></p></li><li><p><a href="./../../中层/世界/神机谋划" class="layer-link" data-layer="中层">神机谋划</a></p></li></ul><hr>',50)])])}const q=r(l,[["render",n]]);export{p as __pageData,q as default};
